    [63051] = {
        id = 63051,
        text = "Hay 2 tipos de tarjetas de entrenamiento: tarjeta mensual y tarjeta semanal. Sobre la compra, te convertirás instantáneamente en entrenador. \nPuedes mejorar a Tohka IA en varias forma: arreglar asuntos en la pantalla de fallas, desagradar respuestas equivocadas y participar en el laboratorio de entrenamiento. Los usuarios activos se enlistarán en la clasificación de espíritu IA y gana marcos de avatar y títulos exclusivos. \nLas tarjetas de entrenamiento expiran 1 semana/mes a partir de la compra y puedes seguir entrenando después o actualizar la clasificación de entrenamiento y la información de entrenador antes de renovarla. \nPuedes renovar las tarjetas para continuar tu entrenamiento.",
        minipack = 0,
    },
    [13322035] = {
        id = 13322035,
        text = "1. There are many ancient civilizations in this world. Dispatch airships to explore them, and complete civilization events to unlock more continents.",
