    [2200110] = {
        id = 2200110,
        text = "Blande a Sandalphon para atacar a los enemigos adyacentes, haciendo 3 ataques directos. \nAtaque 1: Inflige DAÑO físico equivalente al 60% de ATQ 1 vez; \nAtaque 2: Inflige DAÑO físico equivalente al 70% de ATQ 1 vez; \nAtaque 3: Inflige DAÑO físico equivalente al 70% de ATQ 1 vez.",
        minipack = 0,
    },
    [13322107] = {
        id = 13322107,
        text = "In Norse mythology, this evil black dragon lurks at Tree of World's root and gnaws at it constantly. Known as the darkest Dragon King, it has the evil power to subvert Midgard and Asgard. Airship \"Nidhogg\" has the same destructive power as the Black Dragon King and is hold in awe by people of the world",
        minipack = 0,
    },
    [2200120] = {
