    [244012] = {
        id = 244012,
        text = "[Young Maid] studied diligently and her modified cappuccino became a customer favorite.",
        minipack = 0,
    },
    [63052] = {
        id = 63052,
        text = "Puedes hacer Tohka IA mejor de varias maneras: arregla problemas en la ventana de fallas, dale no me gusta a respuestas incorrectas y participa en el laboratorio de entrenamiento. \nPantalla de fallas: registra todas las respuestas de no me gusta para Tohka IA y las preguntas. Puedes unirte a la simulación para entrenar a Tohka IA. Una vez que tu envío sea verificado, la pregunta se borrará de la pantalla de fallas y tu respuesta verificada se convertirá en una nueva respuesta \"posible\" para esa pregunta. \nDale no me gusta a las respuestas de IA al hablar con Tohka IA, toca \"No me gusta\" para bajar el voto de las respuestas incorrectas, después puedes dar otra respuesta o cambiar la pregunta. \nLaboratorio de entrenamiento: Envía las preguntas para entrenar con Tohka IA. Escribe una respuesta que realmente puedas responder, establece una condición de disparo y después envía tu trabajo. \nLista de verificación: registra los estados de contenido del entrenamiento.",
        minipack = 0,
    },
    [2200160] = {
