    },
    [1701171] = {
        id = 1701171,
        text = "Je je… me hace cosquillas… Oh, ¿quieres acariciar a Yoshinon? Aya, ¡no jugaré malas pasadas! ¡Ja ja!",
        minipack = 0,
    },
    [1701172] = {
        id = 1701172,
        text = "Zzz… ¡No - no hagas esto! Ya no soy un niño",
