    },
    [1701174] = {
        id = 1701174,
        text = "Zzz… hermano tondo... ¿Ya no puedes reprimir tu lado animal?",
        minipack = 0,
    },
    [1701175] = {
        id = 1701175,
        text = "Zzz… *Bostezo*... ¿Ya es tan tarde? Ehm, terminaré pronto. Por favor, ve a la cama.",
        minipack = 0,
    },
    [1701176] = {
        id = 1701176,
        text = "... Oye... Solo habla conmigo un rato… no es porque me sienta solo.",
        minipack = 0,
    },
    [1701177] = {
        id = 1701177,
        text = "*Suspiro*... Vas a ser una consentida. ¿Qué voy a hacer contigo?",
        minipack = 0,
    },
    [1701178] = {
        id = 1701178,
        text = "... No te preocupes por mí. Sal con otros espíritus",
        minipack = 0,
    },
    [1701179] = {
        id = 1701179,
        text = "Por qué.. ¿por qué debo quedarme? He terminado mi misión.",
        minipack = 0,
    },
    [1701180] = {
        id = 1701180,
        text = "¡…! ¿Quieres abrazarme?... Espera, ¿qué debería hacer?",
        minipack = 0,
    },
    [1701181] = {
        id = 1701181,
        text = "Ja ja… Resulta que tus manos están calientes.",
        minipack = 0,
    },
    [1701182] = {
        id = 1701182,
        text = "Ehm… mantente con vida. Puedo- sentirlo.",
        minipack = 0,
    },
    [1701183] = {
        id = 1701183,
        text = "¿En verdad? Yo… ¿puedo quedarme aquí? ¿Lo dices en serio?",
        minipack = 0,
    },
    [1701184] = {
        id = 1701184,
        text = "Yo… Ya no soy una existencia que naciera para desaparecer...",
        minipack = 0,
    },
    [1701185] = {
