        minipack = 0,
    },
    [1701486] = {
        id = 1701486,
        text = "Kukuku, deja que el avatar del viento nos guíe hasta el fin del infierno.",
        minipack = 0,
    },
    [1701487] = {
        id = 1701487,
        text = "Ah, estoy tan feliz… (Tos) ¡Hasta el viento parece bailar!",
        minipack = 0,
    },
    [1701488] = {
        id = 1701488,
        text = "¿Viste a través de mí? ¿Tienes tus ojos mágicos fortalecidos?",
        minipack = 0,
    },
    [1701489] = {
        id = 1701489,
        text = "Gracias por hoy… *Tos*, la aventura es maravillosa. Invítame nuevamente la próxima vez.",
        minipack = 0,
    },
    [1701490] = {
        id = 1701490,
        text = "Lo siento, no leí el ambiente.",
        minipack = 0,
    },
    [1701491] = {
        id = 1701491,
        text = "Eso es más probable, ¡lo espero con ansias!",
        minipack = 0,
    },
    [1701492] = {
        id = 1701492,
        text = "Sí… *Tos*, está bien, solo ve a sacrificarte por tu fe.",
        minipack = 0,
    },
    [1701493] = {
        id = 1701493,
        text = "No hay problema. ¡Conozco bien sobre ropa!",
        minipack = 0,
    },
    [1701494] = {
        id = 1701494,
        text = "Vamos, ¡hazme un cumplido! (tono chunibyo anticuado)",
        minipack = 0,
    },
    [1701495] = {
        id = 1701495,
        text = "¡Este! Combina perfectamente con la lanza negra, ¡maravilloso!",
        minipack = 0,
    },
    [1701496] = {
        id = 1701496,
        text = "Pariente mío, ¿por qué estás aquí?",
        minipack = 0,
    },
    [1701497] = {
        id = 1701497,
        text = "Oye… ¿no dirás nada?... No lo hagas tan incómodo.",
        minipack = 0,
    },
    [1701498] = {
        id = 1701498,
        text = "Ehm, has preparado ofrendas. Te daré la mitad dMundo.",
        minipack = 0,
    },
    [1701499] = {
        id = 1701499,
        text = "Interesante. Como recompensa, te daré la mitad dMundo.",
        minipack = 0,
    },
    [1701500] = {
        id = 1701500,
        text = "Gracias por tu esfuerzo. Puedo elogiarte. (tono chunibyo ancestral)… ¿Qué? No, ¡hablo en serio!",
        minipack = 0,
    },
    [1701501] = {
        id = 1701501,
        text = "Kuku, lindas ofrendas, lo has hecho bien.",
        minipack = 0,
    },
    [1701502] = {
        id = 1701502,
        text = "Jum, he acumulado \"Karma\"… (tono chunibyo anticuado) ¿Qué? ¿No es necesario? ¿A qué te refieres? (tono juvenil)",
        minipack = 0,
    },
    [1701503] = {
        id = 1701503,
        text = "Pariente mío, ¿para qué me has invocado?",
        minipack = 0,
    },
    [1701504] = {
        id = 1701504,
        text = "¡Tal vez derrote a Yuzuru la próxima vez!",
        minipack = 0,
    },
    [1701505] = {
        id = 1701505,
        text = "Kuku, bueno, hablaré contigo un rato. Deberías sentirte honrado. (Nota: tono chunibyo ancestral)",
        minipack = 0,
    },
    [1701506] = {
        id = 1701506,
        text = "¡Avatar del viento - Kaguya Yamai está aquí! (tono chunibyo ancestral)",
        minipack = 0,
    },
    [1701507] = {
        id = 1701507,
        text = "¡Kukuku! ¡Soy imparable! (tono chunibyo anticuado)",
        minipack = 0,
    },
    [1701508] = {
        id = 1701508,
        text = "¿Quieres ver mi habilidad?",
        minipack = 0,
    },
    [1701509] = {
        id = 1701509,
        text = "¡Vamos a luchar, Yuzuru!",
        minipack = 0,
    },
    [1701510] = {
        id = 1701510,
        text = "Esperar. ¿Con qué accidente me toparé esta vez?",
        minipack = 0,
    },
    [1701511] = {
        id = 1701511,
        text = "Elogiar. Una cita muy placentera",
        minipack = 0,
    },
    [1701512] = {
        id = 1701512,
        text = "Sorprendido. [Me atrapaste] (Sin emociones).",
        minipack = 0,
    },
    [1701513] = {
        id = 1701513,
        text = "Placentero. Nunca pensé que sería tan interesante.",
        minipack = 0,
    },
    [1701514] = {
        id = 1701514,
        text = "Mal juzgado. Yuzuru estaba demasiado apresurada.",
        minipack = 0,
    },
    [1701515] = {
        id = 1701515,
        text = "Exitoso. Todo va de acuerdo al plan.",
        minipack = 0,
    },
    [1701516] = {
        id = 1701516,
        text = "Entendido. Te invitaré nuevamente.",
        minipack = 0,
    },
    [1701517] = {
        id = 1701517,
        text = "De acuerdo. Me pregunto qué clase de ropa elegirás para Yuzuru.",
        minipack = 0,
    },
    [1701518] = {
        id = 1701518,
        text = "Pregunta. ¿Kaguya también tiene esta ropa?",
        minipack = 0,
    },
    [1701519] = {
        id = 1701519,
        text = "Maravilloso. Kaguya lo describirá con una de esas palabras elegantes.",
        minipack = 0,
    },
    [1701520] = {
        id = 1701520,
        text = "Cariado. ¿Qué quieres hacer con Yuzuru en esta clase de lugar?",
        minipack = 0,
    },
    [1701521] = {
        id = 1701521,
        text = "Listos. Entrando en modo de batería baja.",
        minipack = 0,
    },
    [1701522] = {
        id = 1701522,
        text = "Elogiar. Es difícil encontrar este tipo de comida deliciosa incluso en el paraíso.",
        minipack = 0,
    },
    [1701523] = {
        id = 1701523,
        text = "Aceptable. Ya que viene de ti, no me contendré.",
        minipack = 0,
    },
    [1701524] = {
        id = 1701524,
        text = "Apuntar. Cuando las chicas dicen [es muy hermosa], debes responder [tú eres más hermosa].",
        minipack = 0,
    },
    [1701525] = {
        id = 1701525,
        text = "Me gusta. Gracias, estoy feliz.",
        minipack = 0,
    },
    [1701526] = {
        id = 1701526,
        text = "Consentir. El lazo está fortalecido",
        minipack = 0,
    },
    [1701527] = {
        id = 1701527,
        text = "Solicitar. ¿Tienes tiene para una bebida fría?",
        minipack = 0,
    },
    [1701528] = {
        id = 1701528,
        text = "Potenciar. ¿Desperdiciar recursos en una persona inútil? Como Kagu.",
        minipack = 0,
    },
    [1701529] = {
        id = 1701529,
        text = "Pregunta. ¿Por qué estás viendo fijamente a Yuzuru?",
        minipack = 0,
    },
    [1701530] = {
        id = 1701530,
        text = "Atención. Hay un olor a peligro en el aire.",
        minipack = 0,
    },
    [1701531] = {
        id = 1701531,
        text = "Orgulloso. Yuzuru se ha vuelto más fuerte.",
        minipack = 0,
    },
    [1701532] = {
        id = 1701532,
        text = "Mostrar. ¿Qué datos quieres ver? ¿O quieres algo más que datos?",
        minipack = 0,
    },
    [1701533] = {
        id = 1701533,
        text = "Competencia. Kaguya, Yuzura hará su mejor esfuerzo esta vez.",
        minipack = 0,
    },
    [1701534] = {
        id = 1701534,
        text = "*Suspiro* Lo siento, no tengo interés en niños.",
        minipack = 0,
    },
    [1701535] = {
        id = 1701535,
        text = "Nunca pensé que esto sería más divertido que luchar.",
        minipack = 0,
    },
    [1701536] = {
        id = 1701536,
        text = "Jum, buen desempeño.",
        minipack = 0,
    },
    [1701537] = {
        id = 1701537,
        text = "¿Así que esto se siente tener una cita? Parece interesante.",
        minipack = 0,
    },
    [1701538] = {
        id = 1701538,
        text = "Aburrido- aburrido- no me pidas que vuelva a hacer esto.",
        minipack = 0,
    },
    [1701539] = {
        id = 1701539,
        text = "Recuerda llegar a tiempo, es una orden.",
        minipack = 0,
    },
    [1701540] = {
        id = 1701540,
        text = "¿Cómo te atreves a rechazarme? (Amenazante)",
        minipack = 0,
    },
    [1701541] = {
        id = 1701541,
        text = "¿Nueva armadura de combate?",
        minipack = 0,
    },
    [1701542] = {
        id = 1701542,
        text = "Qué problemático… ¿por qué debería usar este tipo de ropa?",
        minipack = 0,
    },
    [1701543] = {
        id = 1701543,
        text = "Como lo esperaba, la ropa común no es tan divertida como la armadura.",
        minipack = 0,
    },
    [1701544] = {
        id = 1701544,
        text = "¿Hay algún arma nueva?",
        minipack = 0,
    },
    [1701545] = {
        id = 1701545,
        text = "Muéstrame lo que tienes.",
        minipack = 0,
    },
    [1701546] = {
        id = 1701546,
        text = "Uh. Bueno, no está mal. Gracias por tu esfuerzo. Vete.",
        minipack = 0,
    },
    [1701547] = {
        id = 1701547,
        text = "No está mal, pero tal vez algo más de creatividad estaría bien.",
        minipack = 0,
    },
    [1701548] = {
        id = 1701548,
        text = "¿Uh?... Se ve diferente. No puedo aceptarlo. Pero no lo tomes a mal.",
        minipack = 0,
    },
    [1701549] = {
        id = 1701549,
        text = "¿Qué es esto? Si quieres complacerme, investiga un poco.",
        minipack = 0,
    },
    [1701550] = {
        id = 1701550,
        text = "Bueno, bueno… ser elogiada por alguien como tú no me hará feliz.",
        minipack = 0,
    },
    [1701551] = {
        id = 1701551,
        text = "¡Soy la maga más poderosa!",
        minipack = 0,
    },
    [1701552] = {
        id = 1701552,
        text = "Justo a tiempo para ver mi nuevo equipo.",
        minipack = 0,
    },
    [1701553] = {
        id = 1701553,
        text = "¿Qué pasa? Si no es nada, ¿podrías dejarme sola?",
        minipack = 0,
    },
    [1701554] = {
        id = 1701554,
        text = "Sólo déjaselo al personaje más poderoso: yo.",
        minipack = 0,
    },
    [1701555] = {
        id = 1701555,
        text = "Porque soy la más fuerte.",
        minipack = 0,
    },
    [1701556] = {
        id = 1701556,
        text = "¡Sí! ¡Soy yo en mi máxima forma!",
        minipack = 0,
    },
    [1701557] = {
        id = 1701557,
        text = "¡Veamos quién se atraviesa en mi camino!",
        minipack = 0,
    },
    [1701558] = {
        id = 1701558,
        text = "Ehm je je, ¿a dónde me llevas?",
        minipack = 0,
    },
    [1701559] = {
        id = 1701559,
        text = "Cariño es el mejor. Hoy estoy súper feliz.",
        minipack = 0,
    },
    [1701560] = {
        id = 1701560,
        text = "Me gusta mucho más cariño.",
        minipack = 0,
    },
    [1701561] = {
        id = 1701561,
        text = "Vas a aprender a ser paciente, cariño.",
        minipack = 0,
    },
    [1701562] = {
        id = 1701562,
        text = "La \"fiesta\" de hoy transcurrió sin problemas.",
        minipack = 0,
    },
    [1701563] = {
        id = 1701563,
        text = "¿Necesitas una llamada como recordatorio? Cariño, no llegues tarde.",
        minipack = 0,
    },
    [1701564] = {
        id = 1701564,
        text = "¿Por qué? ¿No quieres escucharme cantar? (Ofendida, llorando)",
        minipack = 0,
    },
    [1701565] = {
        id = 1701565,
        text = "¿Quieres verme en este nuevo disfraz?",
        minipack = 0,
    },
    [1701566] = {
        id = 1701566,
        text = "¡Buena reacción! ¿Acaso te hipnotizo?",
        minipack = 0,
    },
    [1701567] = {
        id = 1701567,
        text = "Cariño, mira, ¿qué tal este disfraz?",
        minipack = 0,
    },
    [1701568] = {
        id = 1701568,
        text = "Cariño, ¿tienes un regalo para mí? ¡Estoy tan feliz!",
        minipack = 0,
    },
    [1701569] = {
        id = 1701569,
        text = "Cariño, ¿tienes un regalo para mí? ¡Lo espero con ansias!",
        minipack = 0,
    },
    [1701570] = {
        id = 1701570,
        text = "¡Ehm! ¡Qué sabroso! Puedo sentir en él el amor de cariño.",
        minipack = 0,
    },
    [1701571] = {
        id = 1701571,
        text = "Ara, se ve sabroso. ¿Puedo aceptarlo?",
        minipack = 0,
    },
    [1701572] = {
        id = 1701572,
        text = "¡Guau! ¡Gracias! Para corresponder a este regalo, ¡puedo darte un abrazo!",
        minipack = 0,
    },
    [1701573] = {
        id = 1701573,
        text = "Gracias. ¡Lo atesoraré!",
        minipack = 0,
    },
    [1701574] = {
        id = 1701574,
        text = "¡Me agradas mucho, cariño!",
        minipack = 0,
    },
    [1701575] = {
        id = 1701575,
        text = "Lalala, cariño, ¿quieres escucharme cantar?",
        minipack = 0,
    },
    [1701576] = {
        id = 1701576,
        text = "Hablo en serio. ¡Cómo se atreven a interrumpir nuestra cita! Qué molesto, jum.",
        minipack = 0,
    },
    [1701577] = {
        id = 1701577,
        text = "Digo, no obtendrás mi autógrafo si te quedas solo mirando así.",
        minipack = 0,
    },
    [1701578] = {
        id = 1701578,
        text = "Hola, gracias por preguntarme, cariño. ¡Soy tu Miku!",
        minipack = 0,
    },
    [1701579] = {
        id = 1701579,
        text = "¡Puedo cantar aún mejor ahora!",
        minipack = 0,
    },
    [1701580] = {
        id = 1701580,
        text = "La batalla no es para damas, pero por cariño, puedo hacer lo que sea.",
        minipack = 0,
    },
    [1701581] = {
        id = 1701581,
        text = "¡Déjame protegerte, cariño!",
        minipack = 0,
    },
    [1701582] = {
        id = 1701582,
        text = "Es como si estuviera en un sueño. Como todos los demás, ahora puedo salir contigo.",
        minipack = 0,
    },
    [1701583] = {
        id = 1701583,
        text = "Je je, nunca pensé que sería tan feliz.",
        minipack = 0,
    },
    [1701584] = {
        id = 1701584,
        text = "Ara, me atrapaste, je je.",
        minipack = 0,
    },
    [1701585] = {
        id = 1701585,
        text = "No importa cuántas veces venga, siempre disfrutaré este lugar.",
        minipack = 0,
    },
    [1701586] = {
        id = 1701586,
        text = "Sin prisa, tómate tu tiempo.",
        minipack = 0,
    },
    [1701587] = {
        id = 1701587,
        text = "Entonces te veo más tarde, lo espero con ansias.",
        minipack = 0,
    },
    [1701588] = {
        id = 1701588,
        text = "Está bien. Trabajemos duro la próxima vez.",
        minipack = 0,
    },
    [1701589] = {
        id = 1701589,
        text = "¿Tienda de ropa? Tantos recuerdos divertidos de ahí, je je.",
        minipack = 0,
    },
    [1701590] = {
        id = 1701590,
        text = "¿Me queda bien?... Je je, qué bueno que te gustara.",
        minipack = 0,
    },
    [1701591] = {
        id = 1701591,
        text = "Este vestido es tan bonito. ¿Te gusto más ahora?",
        minipack = 0,
    },
    [1701592] = {
        id = 1701592,
        text = "¿Ehm? ¿Te escabulliste para encontrarme? Je je.",
        minipack = 0,
    },
    [1701593] = {
        id = 1701593,
        text = "Oh, ¿quieres darme un regalo?",
        minipack = 0,
    },
    [1701594] = {
        id = 1701594,
        text = "Este sabor… No lo había probado antes.",
        minipack = 0,
    },
    [1701595] = {
        id = 1701595,
        text = "Gracias, en verdad es delicioso.",
        minipack = 0,
    },
    [1701596] = {
        id = 1701596,
        text = "Me hace muy feliz que siempre sepas lo que me gusta.",
        minipack = 0,
    },
    [1701597] = {
        id = 1701597,
        text = "¡En serio! ¿En verdad es para mí?",
        minipack = 0,
    },
    [1701598] = {
        id = 1701598,
        text = "Como siempre, te amo profundamente… solo bromeaba.",
        minipack = 0,
    },
    [1701599] = {
        id = 1701599,
        text = "¿Me extrañaste? Está bien, estaré aquí.",
        minipack = 0,
    },
    [1701600] = {
        id = 1701600,
        text = "Puedo sentir, la fuerza de todos.",
        minipack = 0,
    },
    [1701601] = {
        id = 1701601,
        text = "¿Qué pasa?",
        minipack = 0,
    },
    [1701602] = {
        id = 1701602,
        text = "Soy la adjudicadora. Veré a través de ti.",
        minipack = 0,
    },
    [1701603] = {
        id = 1701603,
        text = "Entonces… puedo protegerte.",
        minipack = 0,
    },
    [1701604] = {
        id = 1701604,
        text = "Comparada con otros, no soy lo suficientemente buena.",
        minipack = 0,
    },
    [1701605] = {
        id = 1701605,
        text = "Por aquel a quien amo, haré mi mejor esfuerzo.",
        minipack = 0,
    },
