    [1701991] = {
        id = 1701991,
        text = "Ja, ¿cita…? ¿Conmigo? ¿Es en serio?",
        minipack = 0,
    },
    [1701992] = {
        id = 1701992,
        text = "¿Qué haríamos hoy?",
        minipack = 0,
    },
    [1701993] = {
        id = 1701993,
        text = "Eres un tanto rudo…",
        minipack = 0,
    },
    [1701994] = {
        id = 1701994,
        text = "Cita… suena divertido… no, nada.",
        minipack = 0,
    },
    [1701995] = {
        id = 1701995,
        text = "Pero qué diablos...",
        minipack = 0,
    },
    [1701996] = {
        id = 1701996,
        text = "Si quieres rechazarme, dilo ahora. ¿Eso está en verdad permitido?",
