    [1701997] = {
        id = 1701997,
        text = "Ah, bien, me imaginaba. No estoy molesta para nada. Esto solo es normal.",
        minipack = 0,
    },
    [1701998] = {
        id = 1701998,
        text = "Digo, no hay nada que valga la pena mirar.",
        minipack = 0,
