    [1702053] = {
        id = 1702053,
        text = "[Principal] Natsumi_Capítulo 1",
        minipack = 0,
    },
    [1702054] = {
        id = 1702054,
        text = "La doncella de cabello tan oscuro como la noche, tiene los ojos tan brillantes como las estrellas en el cielo.",
        minipack = 0,
    },
    [1702055] = {
        id = 1702055,
        text = "Ni siquiera la identidad de una fuerte guerrera puede esconder su corazón de niña.",
        minipack = 0,
    },
    [1702056] = {
        id = 1702056,
        text = "Con un corazón tan frágil como el cristal, le teme a los extraños y necesita de tus cuidados.",
        minipack = 0,
    },
    [1702057] = {
        id = 1702057,
        text = "Fuerza poderosa y cruel, con una belleza aun más mortal.",
        minipack = 0,
    },
    [1702058] = {
        id = 1702058,
        text = "Intenta conservar la calma todo el tiempo. Sin embargo, siempre se pierde en la calidez de su hermano.",
        minipack = 0,
    },
    [1702059] = {
        id = 1702059,
        text = "El [Amor] es la única razón de su existencia. Se queda en la cima como un ángel.",
        minipack = 0,
    },
    [1702060] = {
        id = 1702060,
        text = "Solo le revela su verdadero ser a aquellos en quien confía.",
        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "¿Día de San Valentín? Vaya… Mientras pueda salir contigo, diré que ha sido un buen día. \nEstar conmigo también te hace feliz, ¿verdad?",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "Amor mío, espero que aceptes mi flor y carta de amor. \nVen, ¡pasa esta hermosa noche conmigo!",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
        text = "Yoshino ya es más fuerte que antes…\nFe- feliz día de San Valentín.",
        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "Ara, aunque estaba destinado de este modo, a veces me siento afortunada \npor verte en el río del tiempo.",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "Tonto hermano mayor, este festival es para los enamorados, pero sí que tengo algo que decirte. \nGracias por estar ahí para mí, todo el tiempo.",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "Hoy, sostendré tu mano al caminar en la llanura floreciente, o bajo la lluvia de pétalos en el bosque. \nHasta que nuestra sombra se alargue en la luz del atardecer.",
        minipack = 0,
    },
    [1702067] = {
        id = 1702067,
        text = "De hecho, Actually, sí quiero sincerarme contigo a veces...\nPero estoy esperando la perfecta ocasión.",
        minipack = 0,
    },
