    },
    [1702135] = {
        id = 1702135,
        text = "Conjunto de comandante",
        minipack = 0,
    },
    [1702136] = {
        id = 1702136,
        text = "Ara, ara, no seas travieso.",
        minipack = 0,
    },
    [1702137] = {
        id = 1702137,
        text = "Ehm je je, ¿quieres ver que hay dentro? Pero, no- permitido.",
        minipack = 0,
    },
    [1702138] = {
        id = 1702138,
        text = "De hecho… está bien. Incluso si me recuestas sobre tu cama, estoy de acuerdo con eso.",
        minipack = 0,
    },
    [1702139] = {
        id = 1702139,
        text = "Eso es grosero. ¿Qué haces hablando con una chica [ordinaria] como yo?",
        minipack = 0,
    },
    [1702140] = {
