        minipack = 0,
    },
    [1702146] = {
        id = 1702146,
        text = "¡Jo jo! ¿Me veo linda? Es la primera vez que uso ropa así.",
        minipack = 0,
    },
    [1702147] = {
        id = 1702147,
        text = "¡Mira! Sedosa y suave, ¡tan cómoda!",
        minipack = 0,
    },
    [1702148] = {
        id = 1702148,
        text = "Vaya, es difícil caminar con esta ropa…",
        minipack = 0,
    },
    [1702149] = {
        id = 1702149,
        text = "¡Vaya, el vestido está por caer! ¡Ayúdame con él!",
        minipack = 0,
    },
    [1702150] = {
        id = 1702150,
        text = "Mira, un tocado de Sakura, ¿no es bonito?",
        minipack = 0,
    },
    [1702151] = {
        id = 1702151,
        text = "Vaya… se siente incómodo sin ropa interior…",
        minipack = 0,
    },
    [1702152] = {
        id = 1702152,
        text = "Vaya… al parecer he comido demasiado, el cinturón está demasiado ajustado… Uhm, ¿puedes llevarme cargando en tu espalda?",
        minipack = 0,
    },
    [1702153] = {
        id = 1702153,
        text = "Cambié mi horquilla por un tocado de flor especial. ¿Se ve bonito?",
        minipack = 0,
    },
    [1702154] = {
        id = 1702154,
        text = "No es necesaria la ropa interior cuando usas kimono.",
