    [1702396] = {
        id = 1702396,
        text = "¿Cancelar todos los cambios realizados esta vez?",
        minipack = 0,
    },
    [1702397] = {
        id = 1702397,
        text = "¡Mamá, hay un extraño ojisan aquí!",
        minipack = 0,
    },
    [1702398] = {
        id = 1702398,
        text = "Tsk, el cuerpo encogido es realmente inconveniente…",
        minipack = 0,
    },
    [1702399] = {
        id = 1702399,
        text = "Necesito ir al baño. Pero no puedo hacerlo yo misma.",
        minipack = 0,
    },
    [1702400] = {
        id = 1702400,
        text = "Quiero galletas. Dame algunas.",
        minipack = 0,
    },
    [1702401] = {
        id = 1702401,
        text = "Mi nombre es Chiyogami. Gusto en conocerte.",
        minipack = 0,
    },
    [1702402] = {
        id = 1702402,
        text = "Soy el fruto del amor de mis padres.",
        minipack = 0,
    },
    [1702403] = {
        id = 1702403,
        text = "Papá, no hagas nada estúpido.",
        minipack = 0,
    },
    [1702404] = {
        id = 1702404,
        text = "Clase 3A",
        minipack = 0,
    },
    [1702405] = {
        id = 1702405,
        text = "Chiyogami Itsuka",
        minipack = 0,
    },
    [1702406] = {
        id = 1702406,
        text = "Hasta la casa más pequeña debe tener una entrada amplia para mostrar cortesía a los visitantes. ¡También es en donde ocurre la \"interacción especial\" con los espíritus!",
        minipack = 0,
    },
    [1702407] = {
        id = 1702407,
        text = "",
        minipack = 0,
    },
    [1702408] = {
        id = 1702408,
        text = "",
        minipack = 0,
