    [1702409] = {
        id = 1702409,
        text = "",
        minipack = 0,
    },
    [1702410] = {
        id = 1702410,
        text = "",
        minipack = 0,
    },
    [1702411] = {
        id = 1702411,
        text = "An average home. This angle is great.",
        minipack = 0,
    },
    [1702412] = {
        id = 1702412,
        text = "",
        minipack = 0,
    },
    [1702413] = {
        id = 1702413,
        text = "",
        minipack = 0,
    },
    [1702414] = {
        id = 1702414,
        text = "",
        minipack = 0,
    },
    [1702415] = {
        id = 1702415,
        text = "",
        minipack = 0,
    },
    [1702416] = {
        id = 1702416,
        text = "Durante la construcción de este apartamento, Kotori quería que los espíritus vivieran en un mundo color de rosa. Hasta la orgullosa Kurumi tiene su lado amable, ¿verdad? (Aunque al final, ella no vive aquí^0^)",
        minipack = 0,
    },
    [1702417] = {
        id = 1702417,
        text = "Para aprender más sobre la vida diaria de los espíritus, visita su estancia más seguido. Hasta puedes conseguir algún \"servicio\" especial.",
        minipack = 0,
    },
    [1702418] = {
        id = 1702418,
        text = "Aquí es donde los espíritus duermen por la noche. Espero que la habitación con la vista nocturna de Ciudad Tengu les proporcione un sueño romántico.",
        minipack = 0,
    },
    [1702419] = {
        id = 1702419,
        text = "Cada noche, en la estancia donde viven los espíritus, si la TV está encendida, seguramente escucharás el llanto de Yoshinon y el grito de Natsumi. Eso quiere decir que hay drama.",
        minipack = 0,
    },
    [1702420] = {
        id = 1702420,
        text = "",
        minipack = 0,
    },
    [1702421] = {
        id = 1702421,
        text = "",
        minipack = 0,
    },
    [1702422] = {
        id = 1702422,
        text = "Ni la luz del sol más brillante puede ahuyentar la penumbra en el corazón del espíritu. ¿Por qué un espíritu tiene que sentarse a escuchar a los maestros? Qué dolor de cabeza.",
        minipack = 0,
    },
    [1702423] = {
        id = 1702423,
        text = "Los estudiantes flojos se reunirán a veces en la azotea vacía. Algunos dicen haber visto alguna vez a una misteriosa chica vestida de rojo con un rostro hermoso e inolvidable.",
        minipack = 0,
    },
    [1702424] = {
        id = 1702424,
        text = "El corredor puede recordarle a los estudiantes el castigo de pie. Se vuelve algo ruidoso entre clases, oh, cómo vuela el tiempo...",
        minipack = 0,
    },
    [221001] = {
        id = 221001,
        text = "No existen los datos de cita",
        minipack = 0,
    },
    [1702426] = {
        id = 1702426,
        text = "Se dice que este es el mejor punto para admirar la luna. Pero pocos vendrían aquí de noche, ¿cierto? Si ves la sombre de una chica solitaria, no te sorprendas tanto.",
        minipack = 0,
    },
    [1702427] = {
        id = 1702427,
        text = "El corredor es tranquilo durante la noche, pero no es un buen lugar para una cita. Tal vez a algunos espíritus les gusten este tipo de lugares.",
        minipack = 0,
    },
    [1702428] = {
