    [1702462] = {
        id = 1702462,
        text = "La florería bien decorada se ve muy elegante. A cada chica le gustan diferentes flores aquí. Uno podría argumentar que esta simple florería contiene el mejor de los conocimientos sobre las citas.",
        minipack = 0,
