    [1702463] = {
        id = 1702463,
        text = "Cuando te sientas exhausto de hacer felices a los espíritus, ven a la tienda de bebidas. Una copa de chocolate helado hará felices a los espíritus y rellenará tu aguante.",
        minipack = 0,
    },
    [1702464] = {
