    },
    [14210161] = {
        id = 14210161,
        text = "Estimados covenanters, \n Gracias a la última tecnología proporcionada por Natsumi, el chat IA de Tohka- \"Tohbaka\" se ha unido oficialmente a Ratatoskr. \n Hemos trabajado duro para mejorar el juego y agregar más y mejores contenidos. Más espíritus se estarán uniendo próximamente al chat. ¡Espéralo!\n Hot Games",
        minipack = 0,
    },
    [270456] = {
        id = 270456,
        text = "Diamantes",
        minipack = 0,
    },
    [14210159] = {
        id = 14210159,
        text = "Estimados covenanters, \n Terremotos espaciales violentos en Hot Games hicieron que nuestro servidor de desarrollo colapsara y esto ocasionó un severo impacto en nuestro trabajo y nos orilló a retrasar el lanzamiento. Lamentamos el inconveniente y tomaremos las precauciones pertinentes para prevenir que vuelva a suceder. Gracias a todos por su apoyo\n Hot Games",
        minipack = 0,
    },
