    [3310012] = {
        id = 3310012,
        text = "12. DMG Proportion Reward is a reward for individual Club member. Based on the damage dealt by the individual to all Bosses in current challenge phase, the prize will be given after the event.",
        minipack = 0,
    },
    [3310010] = {
        id = 3310010,
        text = "10. Habrá clasificación individual y de club en estos modos. Los puntos individuales son el daño causado a los jefes por los miembros del club, mientras que los clubes son clasificados por el progreso logrado en el ciclo (mayor nivel de jefe eliminado, daño causado). La clasificación de club se mostrará en el siguiente ciclo.",
